              numeroProduccion: number | null;
              /** @description Id del modelo PADRE del que nació esta versión (V1-E7b), o null si el modelo es raíz. */
              idModeloPadre: number | null;
              /** @description Código del modelo padre (para enseñar el linaje con liga), o null. */
              codigoPadre: string | null;
              /** @description Nº del sufijo de versión del código (`-01` → 1), o null si el modelo no es una versión. */
              versionDesarrollo: number | null;
              /** @description Id del modelo de DESARROLLO del que nació este modelo de PRODUCCIÓN (linaje 1:N, V1-E9a) y de quien es su receta, o null = la receta es la suya. */
              idModeloDesarrollo: number | null;
              /** @description Código del modelo de desarrollo del que nació (para enseñar el linaje), o null. */
              codigoModeloDesarrollo: string | null;
              /** @description Estado de la REVISIÓN de la receta de esta versión, o null si el modelo no lleva revisión (no es una versión). */
              revisionEstado: ('pendiente' | 'aprobada' | 'rechazada') | null;
              /** @description Id de quien firmó la revisión, o null. */
              idRevisadoPor: string | null;
              /** @description Nombre de quien firmó la revisión (para la pantalla), o null. */
              revisadoPor: string | null;
              /** @description Fecha/hora ISO-8601 en que se firmó la revisión, o null. */
              revisadoEn: string | null;
              /** @description Motivo del rechazo, nota de la aprobación, o —desde V1-E7e (§Post-F9.116)— el porqué de la INVALIDACIÓN automática: qué parte de la receta cambió después de firmarse y de cuándo era la firma que se cayó. Null si se firmó sin escribir nada. */
              revisionNota: string | null;
              /** @description Desenlace de la promesa de la mesa, o null = NADIE lo declaró (no significa que se haya cumplido). */
              metaResultado: ('lograda' | 'no_lograda') | null;
              /** @description La META congelada al firmar: el costo con el que se cerró la mesa. Null = no se encontró negociación registrada. */
              metaCostoPrometido: number | null;
              /** @description Lo que SÍ se consiguió (costo por prenda), o null. */
