              total: number;
              /** @description Página solicitada (1-based). */
              pagina: number;
              /** @description Renglones por página. */
              porPagina: number;
              /** @description Total de páginas. */
              totalPaginas: number;
              /** @description Totales del periodo (todo el filtro). */
